import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"7. 常见错误和警告","description":"The Little Book of C 中文版 — 7. 常见错误和警告","frontmatter":{"title":"7. 常见错误和警告","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 7. 常见错误和警告","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":7,"sidebarWeight":7,"alternateZh":"/posts/c教程/zh-CN/01-入门/007-Common Errors and Warnings","alternateEn":"/posts/c教程/en-US/01-Getting Started/007-Common Errors and Warnings"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/007-Common Errors and Warnings.md","filePath":"posts/c教程/zh-CN/01-入门/007-Common Errors and Warnings.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/01-入门/007-Common Errors and Warnings.md"};function i(o,a,l,c,d,r){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/01-Getting Started/007-Common Errors and Warnings)</p><p>没有一个 C 程序员能够避免错误。事实上，编译器的消息是你最好的老师。每个警告或错误都是编译器表达“这里有些东西还没有意义”的方式。尽早学习阅读并修复它们将为您节省数小时的时间，并使调试成为您过程中自然的一部分。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>让我们看几个例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int a = 5</span></span>
<span class="line"><span>    printf(&quot;The value of a is %d\\n&quot;, a);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>尝试编译它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc error_demo.c -o error_demo</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error_demo.c: In function ‘main&#39;:</span></span>
<span class="line"><span>error_demo.c:4:13: error: expected ‘;&#39; before ‘printf&#39;</span></span></code></pre></div><p>这意味着编译器发现缺少分号。该消息甚至会告诉您在哪里（<code>line 4</code>）以及为什么（<code>expected &#39;;&#39; before &#39;printf&#39;</code>).</p><p>通过添加缺少的分号来修复它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int a = 5;</span></span></code></pre></div><p>然后再次编译，输出干净就说明成功了。</p><h4 id="常见错误类型" tabindex="-1">常见错误类型 <a class="header-anchor" href="#常见错误类型" aria-label="Permalink to &quot;常见错误类型&quot;">​</a></h4><p>语法错误 这些是最容易修复的。你违反了语法规则。示例：缺失<code>;</code>, 不匹配的大括号<code>{}</code>，或不正确的括号。</p><p>类型错误 您使用变量或函数的方式与它们的类型不匹配。例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = &quot;hello&quot;; // error: assigning string to int</span></span></code></pre></div><p>未声明的标识符您正在使用编译器尚未见过的变量或函数。例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;Value: %d\\n&quot;, number); // error: ‘number&#39; undeclared</span></span></code></pre></div><p>链接器错误 编译成功，但链接失败，因为缺少某些内容。例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>undefined reference to \`greet&#39;</span></span></code></pre></div><p>这意味着编译器看到了声明，但找不到实际的函数定义。</p><p>警告警告不会停止编译，但它们通常指出潜在的错误。例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>warning: variable ‘x&#39; set but not used</span></span></code></pre></div><p>始终注意警告、干净的构建（<code>no warnings</code>）是质量代码的标志。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>每个程序员都会犯错误。重要的是你能多快地理解编译器所说的内容。在 C 语言中，错误消息通常是精确而诚实的，它们准确地告诉您发生了什么问题。通过学习解释它们，你正在训练自己用逻辑而不是运气进行调试。</p><p>良好习惯：</p><ul><li>经常编译，不要等到写了 100 行才测试。</li><li>使用<code>-Wall -Wextra</code>启用所有有用的警告。</li><li>从上到下阅读错误，第一个错误通常会导致其余错误。</li><li>修复警告，即使代码仍在运行。</li></ul><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>忘记返回类型：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main() {</span></span>
<span class="line"><span>    printf(&quot;No return type!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall test.c</span></span></code></pre></div><p>你会得到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>warning: return type defaults to ‘int&#39;</span></span></code></pre></div><p>使用未声明的变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这将产生：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: ‘x&#39; undeclared</span></span></code></pre></div><p>修复每一个错误，直到你的程序编译干净且没有任何警告为止。</p><p>错误不是失败，它们是编译器引导您理解的方式。你修复的错误越多，你就越能更好地使用机器的语言。</p>`,42)])])}const g=s(p,[["render",i]]);export{u as __pageData,g as default};
